    log_path = os.path.join(session_dir, '../../sessions/', os.path.basename(session_dir) + '.jsonl')
    print(f"Log path: {log_path}")

    try:
        with open(log_path) as f:
            content = f.read()
        # Find demo pairs for task-1b7868f1
        demos = re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content, re.DOTALL)
        for m in demos:
            if '1b7868f1' in m.group(0):
                print(f"\n{m.group(0)[:50]}...")
    except FileNotFoundError:
        print("Log not found yet")
else:
    print("No session dir")

